  SELECT LAST_INSERT_ID()

insert into fina_settlement_applicant (fina_id, fina_info_id, settlement_info_id
  )
values (#{finaId,jdbcType=BIGINT}, #{finaInfoId,jdbcType=BIGINT}, #{settlementInfoId,jdbcType=BIGINT}
  )

mapper.update:
update fina_settlement_applicant
set fina_id = #{finaId,jdbcType=BIGINT},
  fina_info_id = #{finaInfoId,jdbcType=BIGINT},
  settlement_info_id = #{settlementInfoId,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}

update fina_applicant_info f
left join fina_settlement_applicant t on f.id = t.fina_info_id
set f.case_type = #{caseType,jdbcType=INTEGER} where t.settlement_info_id = #{settlementId,jdbcType=BIGINT}

update fina_applicant_info f
left join fina_settlement_applicant t on f.id = t.fina_info_id
set f.applicant_state = #{applicantState,jdbcType=INTEGER}

  ,f.finsh_statement_time = #{finshStatementTime,jdbcType=TIMESTAMP}


  ,f.finsh_applyclaims_time = #{finshApplyclaimsTime,jdbcType=TIMESTAMP}


  ,f.finsh_repayment_time = #{finshRepaymentTime,jdbcType=TIMESTAMP}


  ,f.final_insurance_passed_time = #{finalInsurancePassedTime,jdbcType=TIMESTAMP}

where t.settlement_info_id = #{settlementInfoId,jdbcType=BIGINT}

mapper.select:
select a.* ,f.case_applicant_no as caseApplicantNo ,f.fina_num as finaNum from fina_settlement_applicant a left join fina_applicant_info f on a.fina_info_id = f.id where 1 = 1
and a.fina_info_id = #{finaInfoId,jdbcType=BIGINT}
and a.settlement_info_id = #{settlementInfoId,jdbcType=BIGINT}
order by a.id desc
